def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = max(set(x for row in grid for x in row),
             key=lambda x: sum(row.count(x) for row in grid))
    out = [row[:] for row in grid]

    cells = {}
    for r in range(h):
        for c in range(w):
            if grid[r][c] != bg:
                cells.setdefault(grid[r][c], []).append((r, c))

    for color, pts in cells.items():
        for i, (r1, c1) in enumerate(pts):
            for r2, c2 in pts[i + 1:]:
                dr, dc = r2 - r1, c2 - c1
                if abs(dr) != 1 or abs(dc) != 1:
                    continue

                others = [(r, c) for col, group in cells.items()
                          if col != color for r, c in group]

                def distance_to_others(p):
                    if not others:
                        return float('inf')
                    return min(max(abs(p[0] - r), abs(p[1] - c))
                               for r, c in others)

                # Extend out from the endpoint farther from the other colored cells.
                if distance_to_others((r1, c1)) >= distance_to_others((r2, c2)):
                    r, c, sr, sc = r1, c1, -dr, -dc
                else:
                    r, c, sr, sc = r2, c2, dr, dc

                rr, cc = r + sr, c + sc
                while 0 <= rr < h and 0 <= cc < w:
                    if out[rr][cc] == bg:
                        out[rr][cc] = color
                    rr += sr
                    cc += sc

    return out
